  const hm = now.getHours()*60 + now.getMinutes();
  const parse = s => { const [h,m]=(s||'0:0').split(':').map(Number); return h*60+(m||0); };
  const qs = parse(env.get('QUIET_START')||'21:00');
  const qe = parse(env.get('QUIET_END')||'08:00');
