  return [msg, null];
}
msg.statusCode = 403;
msg.payload = { error: 'Invalid signature' };
node.status({fill:'red',shape:'dot',text:'reject'});
return [null, msg];

function redact(s) {
  if (s == null) return s;
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = s.replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[email-redacted]');
  s = s.replace(/\b(?:\+?1[-. ]?)?(?:\(?\d{3}\)?[-. ]?)\d{3}[-. ]?\d{4}\b/g, '[phone-redacted]');
  s = s.replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[ssn-redacted]');
  return s;
}
